		Error: &app.OperationError{Code: "validation.reference", Category: "validation", Cause: "secret=hidden", Guidance: "Complete execute evidence before review."},
	})
	data, err := json.Marshal(result)
	if err != nil {
		t.Fatal(err)
	}
